type Dict = Record<string, unknown>;

function hasValue(value: unknown): boolean {
  if (value === null || value === undefined) return false;
  if (typeof value === "string") return value.trim().length > 0;
  if (Array.isArray(value)) return value.length > 0;
  return true;
}

function uniq<T>(items: T[]): T[] {
  return [...new Set(items)];
}

function routeDefinitions(): any[] {
  return (EVE_05_GATE_ENGINE as any).modules.critical_route_gate.routes;
}

function semanticDefinitions(): any[] {
  return (EVE_05_GATE_ENGINE as any).modules.semantic_resolution_gate.gate_definitions;
}

function pstDefinitions(): any[] {
  return (EVE_05_GATE_ENGINE as any).modules.process_state_timer_gate.gate_definitions;
}

function conformanceRules(): any[] {
  const mod = (EVE_05_GATE_ENGINE as any).modules.mmabp_conformance_gate;
  return [...mod.engine_rules, ...mod.model_rules];
}

function consistencyRules(): any[] {
  const mod = (EVE_05_GATE_ENGINE as any).modules.mmabp_consistency_gate;
  return [...mod.engine_rules, ...mod.method_rules];
}

export interface CriticalRouteInput {
  routeId: string;
  active: boolean;
  observedSourceCodes?: string[];
  variables?: Dict;
  evidenceRefs?: string[];
  semanticGapUnresolved?: boolean;
  transformationExceptionExists?: boolean;
  transformationHiddenChanges?: boolean;
  deliveryExceptionExists?: boolean;
  feedbackOperationalSignal?: boolean;
  feedbackTextEvidence?: boolean;
  canonicalRouteClosed?: boolean;
  confidenceLevel?: string;
  signalsCrossed?: boolean;
  directProjectionAttempts?: string[];
}

export function evaluateCriticalRouteGate(input: CriticalRouteInput): GateResult {
  const def = routeDefinitions().find((r) => r.route_id === input.routeId);
  if (!def) {
    return {
      module: "critical_route_gate",
      gateId: input.routeId,
      status: "fail",
      blocking: true,
      message: "Ruta crítica desconocida.",
      missingFields: ["route_definition"],
      violations: ["unknown_critical_route"],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "manual_review_required",
    };
  }
  if (!input.active) {
    return {
      module: "critical_route_gate",
      gateId: input.routeId,
      status: "not_applicable",
      blocking: false,
      message: "Ruta no activa para este contexto.",
      missingFields: [],
      violations: [],
      evidenceRefs: input.evidenceRefs ?? [],
    };
  }

  const observed = new Set(input.observedSourceCodes ?? []);
  const missingCodes = (def.source_codes as string[]).filter((c) => !observed.has(c));
  const vars = input.variables ?? {};
  const missingVariables = (def.required_variables as string[]).filter((v) => !hasValue(vars[v]));
  const violations: string[] = [];

  if (input.routeId === "CR-B0-WorkMapIntake-semantic-entry" && input.semanticGapUnresolved) {
    violations.push("semantic_gap_unresolved");
  }
  if (input.routeId === "CR-B2-V3-transformation_exception") {
    if (input.transformationExceptionExists && !hasValue(vars.transformation_exception_description)) {
      missingVariables.push("transformation_exception_description");
    }
    if (input.transformationHiddenChanges && !hasValue(vars.transformation_hidden_changes_description)) {
      missingVariables.push("transformation_hidden_changes_description");
    }
  }
  if (input.routeId === "CR-B3-R9-receiver_feedback") {
    if ((input.deliveryExceptionExists || input.feedbackOperationalSignal) &&
        !hasValue(vars.receiver_feedback_exists)) {
      missingVariables.push("receiver_feedback_exists");
    }
    if (input.feedbackTextEvidence && input.canonicalRouteClosed !== true) {
      violations.push("receiver_feedback_route_missing");
      if (!hasValue(vars.receiver_feedback_route_missing)) {
        missingVariables.push("receiver_feedback_route_missing");
      }
    }
  }
  if (input.routeId === "CR-B7-AHE-boundary_guard" &&
      (input.directProjectionAttempts?.length ?? 0) > 0) {
    violations.push("b7_direct_projection_forbidden");
  }

  const missing = uniq([...missingCodes.map((c) => `source_code:${c}`), ...missingVariables]);
  if (missing.length > 0 || violations.length > 0) {
    return {
      module: "critical_route_gate",
      gateId: input.routeId,
      status: violations.includes("b7_direct_projection_forbidden") ? "manual_review_required" : "fail",
      blocking: true,
      message: "La ruta crítica no cerró conforme a su contrato canónico.",
      missingFields: missing,
      violations,
      evidenceRefs: input.evidenceRefs ?? [],
      reentryTarget: def.reentry_target,
      readinessCandidate: def.failure_state as ReadinessState,
    };
  }

  return {
    module: "critical_route_gate",
    gateId: input.routeId,
    status: "pass",
    blocking: false,
    message: "Ruta crítica cerrada con genealogía, variables y fronteras válidas.",
    missingFields: [],
    violations: [],
    evidenceRefs: input.evidenceRefs ?? [],
  };
}

export interface SemanticResolutionInput {
  gateId: string;
  triggered: boolean;
  outcome?: string;
  projectionAttempted?: boolean;
  evidenceRefs?: string[];
}

export function evaluateSemanticResolutionGate(input: SemanticResolutionInput): GateResult {
  const def = semanticDefinitions().find((g) => g.gate_id === input.gateId);
  if (!def) {
    return {
      module: "semantic_resolution_gate",
      gateId: input.gateId,
      status: "fail",
      blocking: true,
      message: "Gate semántico desconocido.",
      missingFields: ["gate_definition"],
      violations: ["unknown_semantic_gate"],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "manual_review_required",
    };
  }
  if (!input.triggered) {
    return {
      module: "semantic_resolution_gate",
      gateId: input.gateId,
      status: "not_applicable",
      blocking: false,
      message: "Gate no gatillado.",
      missingFields: [],
      violations: [],
      evidenceRefs: input.evidenceRefs ?? [],
    };
  }
  if (!input.outcome) {
    return {
      module: "semantic_resolution_gate",
      gateId: input.gateId,
      status: "gap",
      blocking: true,
      message: "Falta outcome semántico.",
      missingFields: ["outcome"],
      violations: [],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "reentry_required",
    };
  }
  if (!(def.possible_outputs as string[]).includes(input.outcome)) {
    return {
      module: "semantic_resolution_gate",
      gateId: input.gateId,
      status: "fail",
      blocking: true,
      message: "Outcome fuera del diccionario permitido.",
      missingFields: [],
      violations: ["invalid_semantic_outcome"],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "manual_review_required",
    };
  }
  if (input.outcome === "ambiguous") {
    return {
      module: "semantic_resolution_gate",
      gateId: input.gateId,
      status: "ambiguous",
      blocking: true,
      message: "Ambigüedad semántica no resuelta; proyección bloqueada.",
      missingFields: [],
      violations: input.projectionAttempted ? ["projection_attempted_while_ambiguous"] : [],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "manual_review_required",
    };
  }
  return {
    module: "semantic_resolution_gate",
    gateId: input.gateId,
    status: "pass",
    blocking: false,
    message: "Resolución semántica dentro del contrato permitido.",
    missingFields: [],
    violations: [],
    evidenceRefs: input.evidenceRefs ?? [],
  };
}

export interface ProcessStateTimerInput {
  gateId: string;
  triggered: boolean;
  capture?: Dict;
  evidenceRefs?: string[];
}

export function evaluateProcessStateTimerGate(input: ProcessStateTimerInput): GateResult {
  const def = pstDefinitions().find((g) => g.gate_id === input.gateId);
  if (!def) {
    return {
      module: "process_state_timer_gate",
      gateId: input.gateId,
      status: "fail",
      blocking: true,
      message: "Gate PST desconocido.",
      missingFields: ["gate_definition"],
      violations: ["unknown_pst_gate"],
      evidenceRefs: input.evidenceRefs ?? [],
      readinessCandidate: "manual_review_required",
    };
  }
  if (!input.triggered) {
    return {
      module: "process_state_timer_gate",
      gateId: input.gateId,
      status: "not_applicable",
      blocking: false,
      message: "Gate PST no gatillado.",
      missingFields: [],
      violations: [],
      evidenceRefs: input.evidenceRefs ?? [],
    };
  }
  const capture = input.capture ?? {};
  const missing = (def.required_capture as string[]).filter((f) => !hasValue(capture[f]));
  if (missing.length > 0) {
    return {
      module: "process_state_timer_gate",
      gateId: input.gateId,
      status: "gap",
      blocking: true,
      message: "Captura PST incompleta; Process State bloqueado.",
      missingFields: missing,
      violations: ["process_state_contract_incomplete"],
      evidenceRefs: input.evidenceRefs ?? [],
      reentryTarget: "B4/C11",
      readinessCandidate: "reentry_required",
    };
  }
  return {
    module: "process_state_timer_gate",
    gateId: input.gateId,
    status: "pass",
    blocking: false,
    message: "Gate PST satisfecho.",
    missingFields: [],
    violations: [],
    evidenceRefs: input.evidenceRefs ?? [],
  };
}

export interface RuleAssessment {
  status: "pass" | "fail" | "gap" | "ambiguous" | "manual_review_required" | "not_applicable";
  evidenceRefs?: string[];
  notes?: string;
}

export interface ConformanceInput {
  applicableRuleIds: string[];
  assessments: Record<string, RuleAssessment>;
}

export function evaluateMMABPConformanceGate(input: ConformanceInput): {
  results: GateResult[];
  canEnterConsistency: boolean;
} {
  const rules = new Map(conformanceRules().map((r) => [r.id, r]));
  const results: GateResult[] = input.applicableRuleIds.map((ruleId) => {
    const rule: any = rules.get(ruleId);
    const assessment = input.assessments[ruleId];
    if (!rule) {
      return {
        module: "mmabp_conformance_gate",
        gateId: "MMABP-CONFORMANCE",
        ruleId,
        status: "fail",
        blocking: true,
        message: "Regla de conformance desconocida.",
        missingFields: ["rule_definition"],
        violations: ["unknown_conformance_rule"],
        evidenceRefs: [],
        readinessCandidate: "manual_review_required",
      };
    }
    if (!assessment) {
      return {
        module: "mmabp_conformance_gate",
        gateId: "MMABP-CONFORMANCE",
        ruleId,
        status: "gap",
        blocking: true,
        message: "Falta assessment de conformance.",
        missingFields: ["assessment"],
        violations: [],
        evidenceRefs: [],
        reentryTarget: rule.reentry_target ?? rule.model,
        readinessCandidate: "blocked_by_missing_evidence",
      };
    }
    if (assessment.status === "pass" && (assessment.evidenceRefs?.length ?? 0) === 0) {
      return {
        module: "mmabp_conformance_gate",
        gateId: "MMABP-CONFORMANCE",
        ruleId,
        status: "gap",
        blocking: true,
        message: "Un pass sin evidencia no es válido.",
        missingFields: ["evidenceRefs"],
        violations: ["pass_without_evidence"],
        evidenceRefs: [],
        reentryTarget: rule.reentry_target ?? rule.model,
        readinessCandidate: "blocked_by_missing_evidence",
      };
    }
    const blocking = ["fail","gap","ambiguous","manual_review_required"].includes(assessment.status);
    return {
      module: "mmabp_conformance_gate",
      gateId: "MMABP-CONFORMANCE",
      ruleId,
      status: assessment.status,
      blocking,
      message: assessment.notes ?? rule.label,
      missingFields: assessment.status === "gap" ? ["required_evidence"] : [],
      violations: assessment.status === "fail" ? ["conformance_failure"] : [],
      evidenceRefs: assessment.evidenceRefs ?? [],
      reentryTarget: rule.reentry_target ?? rule.model,
      readinessCandidate:
        assessment.status === "fail" ? "blocked_by_contradiction" :
        assessment.status === "gap" ? "blocked_by_missing_evidence" :
        assessment.status === "ambiguous" || assessment.status === "manual_review_required"
          ? "manual_review_required" : undefined,
    };
  });
  return {
    results,
    canEnterConsistency: results.length > 0 && results.every((r) =>
      r.status === "pass" || r.status === "not_applicable"),
  };
}

export interface ConsistencyInput {
  applicableRuleIds: string[];
  assessments: Record<string, RuleAssessment>;
  conformanceByModel: Record<string, "pass" | "fail" | "gap" | "not_applicable">;
}

function modelsFromScope(scope: string | undefined): string[] {
  if (!scope) return [];
  return scope.split("↔").map((x) => x.trim()).filter(Boolean);
}

export function evaluateMMABPConsistencyGate(input: ConsistencyInput): {
  results: GateResult[];
  diagnosticTranslationAllowed: false;
} {
  const rules = new Map(consistencyRules().map((r) => [r.id, r]));
  const results: GateResult[] = input.applicableRuleIds.map((ruleId) => {
    const rule: any = rules.get(ruleId);
    if (!rule) {
      return {
        module: "mmabp_consistency_gate",
        gateId: "MMABP-CONSISTENCY",
        ruleId,
        status: "fail",
        blocking: true,
        message: "Regla de consistencia desconocida.",
        missingFields: ["rule_definition"],
        violations: ["unknown_consistency_rule"],
        evidenceRefs: [],
        readinessCandidate: "manual_review_required",
      };
    }
    const requiredModels = modelsFromScope(rule.model);
    const nonConformant = requiredModels.filter((m) =>
      input.conformanceByModel[m] !== "pass" &&
      input.conformanceByModel[m] !== "not_applicable");
    if (nonConformant.length > 0) {
      return {
        module: "mmabp_consistency_gate",
        gateId: "MMABP-CONSISTENCY",
        ruleId,
        status: "not_evaluated_due_to_conformance",
        blocking: true,
        message: `Consistency diferida: conformance insuficiente en ${nonConformant.join(", ")}.`,
        missingFields: nonConformant.map((m) => `conformance:${m}`),
        violations: [],
        evidenceRefs: [],
        readinessCandidate: "reentry_required",
      };
    }
    const assessment = input.assessments[ruleId];
    if (!assessment) {
      return {
        module: "mmabp_consistency_gate",
        gateId: "MMABP-CONSISTENCY",
        ruleId,
        status: "gap",
        blocking: true,
        message: "Falta assessment de consistencia.",
        missingFields: ["assessment"],
        violations: [],
        evidenceRefs: [],
        readinessCandidate: "blocked_by_missing_evidence",
      };
    }
    if (assessment.status === "pass" && (assessment.evidenceRefs?.length ?? 0) === 0) {
      return {
        module: "mmabp_consistency_gate",
        gateId: "MMABP-CONSISTENCY",
        ruleId,
        status: "gap",
        blocking: true,
        message: "Un pass sin evidencia no es válido.",
        missingFields: ["evidenceRefs"],
        violations: ["pass_without_evidence"],
        evidenceRefs: [],
        readinessCandidate: "blocked_by_missing_evidence",
      };
    }
    const blocking = ["fail","gap","ambiguous","manual_review_required"].includes(assessment.status);
    return {
      module: "mmabp_consistency_gate",
      gateId: "MMABP-CONSISTENCY",
      ruleId,
      status: assessment.status,
      blocking,
      message: assessment.notes ?? rule.label,
      missingFields: assessment.status === "gap" ? ["required_evidence"] : [],
      violations: assessment.status === "fail" ? ["consistency_failure"] : [],
      evidenceRefs: assessment.evidenceRefs ?? [],
      readinessCandidate:
        assessment.status === "fail" ? "blocked_by_contradiction" :
        assessment.status === "gap" ? "blocked_by_missing_evidence" :
        assessment.status === "ambiguous" || assessment.status === "manual_review_required"
          ? "manual_review_required" : undefined,
    };
  });
  return { results, diagnosticTranslationAllowed: false };
}

export interface GateEngineInput {
  criticalRoutes?: CriticalRouteInput[];
  semanticResolutions?: SemanticResolutionInput[];
  processStateTimers?: ProcessStateTimerInput[];
  conformance?: ConformanceInput;
  consistency?: ConsistencyInput;
}

export function evaluateGateEngine(input: GateEngineInput): {
  results: GateResult[];
  blockingResults: GateResult[];
  readinessCandidates: ReadinessState[];
  canProceedToDownstream: boolean;
  finalReadinessDeferredTo: "ReadinessEngine";
  diagnosticTranslationAllowed: false;
} {
  const results: GateResult[] = [];
  for (const item of input.criticalRoutes ?? []) results.push(evaluateCriticalRouteGate(item));
  for (const item of input.semanticResolutions ?? []) results.push(evaluateSemanticResolutionGate(item));
  for (const item of input.processStateTimers ?? []) results.push(evaluateProcessStateTimerGate(item));
  if (input.conformance) results.push(...evaluateMMABPConformanceGate(input.conformance).results);
  if (input.consistency) results.push(...evaluateMMABPConsistencyGate(input.consistency).results);
  const blockingResults = results.filter((r) => r.blocking);
  const readinessCandidates = uniq(
    results.map((r) => r.readinessCandidate).filter(Boolean) as ReadinessState[]
  );
  return {
    results,
    blockingResults,
    readinessCandidates,
    canProceedToDownstream: blockingResults.length === 0,
    finalReadinessDeferredTo: "ReadinessEngine",
    diagnosticTranslationAllowed: false,
  };
}
